export function walkable(room,x,y){return isFloor(room,x,y)&&!geodeObstacleBlocks(room,x,y)&&!mysticBodyBlocks(room,x,y)&&!rootBodyBlocks(room,x,y)&&!room.rocks.some(p=>(p.hp==null||p.hp>0)&&p.x===x&&p.y===y);}
