const PROC_NAMES={lucky:'DANO DUPLO',popcorn:'EXPLOSÃO',ricochet:'RICOCHETE',ember:'QUEIMANDO',ice:'INIMIGO ENFRAQUECIDO',shell:'DANO REDUZIDO',laser:'RAIO EM CRUZ',echohit:'GOLPE EXTRA',bombgift:'BOMBA EXTRA',revival:'NOVA CHANCE'};
function proc(r,id,target=r.player,label){const card=CARDS.find(c=>c.id===id);event(r,'proc',{id,name:label||PROC_NAMES[id]||card.name,color:card.color,x:target.x,y:target.y});}
