 if(target.type==='enemy'&&target.hp>0&&roll('ice')){target.chill={until:beat+4,reduction:value('ice').reduction};if(!target.boss){target.stunUntil=Math.max(target.stunUntil,beat+1);target.windup=null;}proc(r,'ice',target);}
 if(roll('popcorn')){activateFindArea(s,r.player,2,beat,findCallbacks());for(const n of all())if(distance(n,r.player)<=2)damageTarget(s,n,value('popcorn').damage,true);proc(r,'popcorn');event(r,'bomb',{...r.player});}
 if(count('ricochet')){const n=all().filter(n=>n!==target&&distance(n,target)<=5).sort((a,b)=>distance(a,target)-distance(b,target))[0];if(n){damageTarget(s,n,value('ricochet').damage,true);proc(r,'ricochet',n);event(r,'echo',{from:target,x:n.x,y:n.y});}}
