function findCallbacks(){return {maxHealth,damage:(s,target,damage)=>damageTarget(s,target,damage,true,false,false)};}

function advanceMicelial(s,beat){micelialAdvance(s,beat,{...rootCallbacks(s),airborne:at=>activeBoost(s.run,"wings",at)});}
function resolveMicelial(s,beat){micelialResolve(s,beat,{...rootCallbacks(s),airborne:at=>activeBoost(s.run,"wings",at)});}

function advanceMystic(s,beat){mysticAdvance(s,beat,{...rootCallbacks(s),airborne:at=>activeBoost(s.run,"wings",at)});}
function resolveMystic(s,beat){mysticResolve(s,beat,{...rootCallbacks(s),airborne:at=>activeBoost(s.run,"wings",at)});}
